from itertools import permutations

people = ['Casey', 'Jordan', 'Parker', 'Sawyer']
colors = ['blue', 'green', 'orange', 'white']
pets = ['cat', 'fish', 'horse', 'rabbit']
drinks = ['cocoa', 'milk', 'tea', 'water']

def is_valid_configuration(config):
    """Check if a configuration satisfies all clues."""
    # Create position lookup dictionaries
    person_house = {config[i][0]: i for i in range(4)}
    color_house = {config[i][1]: i for i in range(4)}
    pet_house = {config[i][2]: i for i in range(4)}
    drink_house = {config[i][3]: i for i in range(4)}

    # Clue 1: Blue house lives next to horse owner
    if abs(color_house['blue'] - pet_house['horse']) != 1:
        return False

    # Clue 2: Tea drinker immediately left of orange house
    if drink_house['tea'] + 1 != color_house['orange']:
        return False

    # Clue 3: Casey immediately left of rabbit owner
    if person_house['Casey'] + 1 != pet_house['rabbit']:
        return False

    # Clue 4: Cat owner next to orange house
    if abs(pet_house['cat'] - color_house['orange']) != 1:
        return False

    # Clue 5: Parker next to rabbit owner
    if abs(person_house['Parker'] - pet_house['rabbit']) != 1:
        return False

    # Clue 6: Rabbit owner in white house
    if config[pet_house['rabbit']][1] != 'white':
        return False

    # Clue 7: Green house immediately left of rabbit owner
    if color_house['green'] + 1 != pet_house['rabbit']:
        return False

    # Clue 8: Parker is not cocoa drinker
    if config[person_house['Parker']][3] == 'cocoa':
        return False

    # Clue 9: Horse owner immediately left of Sawyer
    if pet_house['horse'] + 1 != person_house['Sawyer']:
        return False

    # Clue 10: Water drinker is Casey
    if config[person_house['Casey']][3] != 'water':
        return False

    return True

# Search for valid configuration using brute force
for people_perm in permutations(people):
    for colors_perm in permutations(colors):
        for pets_perm in permutations(pets):
            for drinks_perm in permutations(drinks):
                config = tuple(zip(people_perm, colors_perm, pets_perm, drinks_perm))
                if is_valid_configuration(config):
                    # Find who drinks water
                    for person, color, pet, drink in config:
                        if drink == 'water':
                            print(f"ANSWER: {person}")
                            exit()
